"""courses service: handler for GET /enrolments/{id}/progress."""

# Catalog records (modules and schemes) only change at deploy time, so they can
# be safely cached for the life of the process. Enrolments and sessions are the
# per-request data and must always be read from the store.
_modules = {}
_schemes = {}


def _fill(store, cache, prefix, ids):
    missing = [i for i in ids if i not in cache]
    if missing:
        fetched = store.get_many(prefix + "%d" % i for i in missing)
        for i in missing:
            record = fetched[prefix + "%d" % i]
            if record is not None:
                cache[i] = record


def handle(store, auth, request):
    user = auth.verify(request["token"])
    enrolment = store.get("enrolment:%d" % request["enrolment_id"])
    student = store.get("student:%d" % enrolment["student_id"])

    module_ids = {item["module_id"] for item in enrolment["items"]}
    _fill(store, _modules, "module:", module_ids)
    _fill(store, _schemes, "scheme:", module_ids)

    lines = []
    total = 0
    for item in enrolment["items"]:
        module = _modules[item["module_id"]]
        scheme = _schemes[item["module_id"]]
        amount = module["points"] * item["attempts"] * (100 - scheme["penalty_percent"]) // 100
        total += amount
        lines.append({"name": module["name"], "amount": amount})
    return {"user": user, "student": student["name"], "lines": lines, "points_total": total}

